mapper.sql:
WHERE chart_accounts.is_active < 2

  AND chart_accounts.id IN (SELECT chart_account_id FROM chart_account_companies WHERE chart_account_companies.company_id = #{filter.companyId})


  AND chart_accounts.chart_account_type_id = #{filter.accountTypeId}


  AND chart_accounts.chart_account_group_id = #{filter.accountGroupId}


  AND ((chart_accounts.account_codes LIKE CONCAT("%", #{filter.searchText}, "%"))
    OR (chart_accounts.account_description LIKE CONCAT("%", #{filter.searchText}, "%")))

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    chart_accounts.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM chart_accounts
WHERE is_active < 2 AND account_codes = #{accountCode}
 AND id != #{id}
